import unreal
mis = unreal.EditorAssetLibrary.list_assets('/Game/EnvSandbox/Meshes/AvatarGarden/Materials/')
for mi_path in mis:
    mi = unreal.EditorAssetLibrary.load_asset(mi_path)
    if mi and 'Paradise' in mi_path:
        suffix = mi_path.split('_')[-1] if '_' in mi_path else ''
        if 'Trans' in suffix:
            mi.set_editor_property('parent', unreal.EditorAssetLibrary.load_asset('/Game/EnvSandbox/Materials/Masters/M_Master_Toon_Universal_Alpha'))
        else:
            mi.set_editor_property('parent', unreal.EditorAssetLibrary.load_asset('/Game/EnvSandbox/Materials/Masters/M_Master_Toon_Universal'))
        mi.set_editor_property('texture_weight', 1.0)
        mi.set_editor_property('layer_a_texture_weight', 1.0)
        unreal.EditorAssetLibrary.save_loaded_asset(mi)
